const fitmentItems = $items('PostgreSQL Search', 0, 0) || [];
const commerceItems = $items('Tecbite Latest Commerce Query', 0, 0) || [];
const thuleItems = $items('Thule Context Query', 0, 0) || [];

const fitment = fitmentItems.length > 0 ? fitmentItems[0].json : null;
const commerce = commerceItems.length > 0 ? commerceItems[0].json : null;
const contextChunks = thuleItems.slice(0, 5).map((item) => item.json);

let commerceStalenessMinutes = null;
if (commerce && commerce.snapshot_at) {
  const nowMs = Date.now();
  const snapshotMs = Date.parse(commerce.snapshot_at);
  if (!Number.isNaN(snapshotMs)) {
    commerceStalenessMinutes = Math.max(0, Math.round((nowMs - snapshotMs) / 60000));
  }
}

const staleHard = commerceStalenessMinutes !== null && commerceStalenessMinutes > 120;
const degradedMode = !commerce || staleHard || contextChunks.length === 0;

const mergedPayload = {
  compatibility: fitment
    ? {
        authority: 'fitment_sql',
        product_sku: fitment.product_sku || null,
        is_compatible: fitment.is_compatible,
        fitment_notes: fitment.fitment_notes || null,
      }
    : {
        authority: 'fitment_sql',
        status: 'no_confirmed_fit',
      },
  commerce: commerce && !staleHard
    ? {
        authority: 'tecbite_snapshot',
        product_sku: commerce.product_sku,
        title: commerce.title,
        price_amount: commerce.price_amount,
        currency: commerce.currency,
        stock_status: commerce.stock_status,
        promo_text: commerce.promo_text,
      }
    : {
        authority: 'tecbite_snapshot',
        status: 'commerce_unavailable_or_stale',
      },
  context: contextChunks.map((chunk) => ({
    authority: 'thule_docs',
    chunk_id: chunk.chunk_id,
    source_url: chunk.source_url,
    locale: chunk.locale,
    text: chunk.chunk_text,
  })),
};

const provenance = {
  fitment_ref: fitment ? `${fitment.brand || ''}:${fitment.model || ''}:${fitment.year_start || ''}-${fitment.year_end || ''}` : null,
  tecbite_snapshot_at: commerce ? commerce.snapshot_at || null : null,
  tecbite_source_url: commerce ? commerce.source_url || null : null,
  thule_chunk_ids: contextChunks.map((chunk) => chunk.chunk_id),
  conflict_flags: staleHard ? ['commerce_stale_hard_threshold'] : [],
};

return [
  {
    json: {
      rowCount: fitmentItems.length,
      merged_payload: mergedPayload,
      provenance,
      routing_decision: {
        fitment: true,
        commerce: !!commerce,
        context: contextChunks.length > 0,
      },
      degraded_mode: degradedMode,
      commerce_staleness_minutes: commerceStalenessMinutes,
      precedence_conflict_count: provenance.conflict_flags.length,
    },
  },
];

